function b64utf8Decode(b64) {
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return new TextDecoder('utf-8').decode(bytes);
}

const APP_HTML_B64 = "";
const APP_HTML = b64utf8Decode(APP_HTML_B64);

/* ==========================================================================
   DB Criações 3D — API backend (Cloudflare Worker + D1)
   ========================================================================== */

function json(data, status) {
  return new Response(JSON.stringify(data), {
    status: status || 200,
    headers: { 'content-type': 'application/json; charset=utf-8' },
  });
}

function uid(prefix) {
  return (prefix || 'id') + '_' + Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
}

function settingsRowToObj(row) {
  return {
    companyName: row.company_name,
    companyLogo: row.company_logo,
    companyPhone: row.company_phone,
    companyEmail: row.company_email,
    companyCnpj: row.company_cnpj,
    companyAddress: row.company_address,
    defaultMargin: row.default_margin,
    defaultMarkup: row.default_markup,
    defaultTaxes: row.default_taxes,
    defaultCardFee: row.default_card_fee,
    defaultEnergyPrice: row.default_energy_price,
    budgetSeq: row.budget_seq,
  };
}

async function getSettings(db) {
  const row = await db.prepare('SELECT * FROM settings WHERE id = 1').first();
  return settingsRowToObj(row);
}

async function getFilaments(db) {
  const { results } = await db.prepare('SELECT * FROM filaments ORDER BY sort_order ASC, name ASC').all();
  return results.map((f) => ({ id: f.id, name: f.name, category: f.category, price: f.price, extrusion: f.extrusion, bed: f.bed, desc: f.desc }));
}

async function getPrinters(db) {
  const { results } = await db.prepare('SELECT * FROM printers ORDER BY sort_order ASC, name ASC').all();
  return results.map((p) => ({ id: p.id, name: p.name, category: p.category, power: p.power, depreciation: p.depreciation, desc: p.desc }));
}

async function getPackagingTypes(db) {
  const { results } = await db.prepare('SELECT * FROM packaging_types ORDER BY sort_order ASC, label ASC').all();
  return results.map((p) => ({ id: p.id, label: p.label }));
}

async function getResolutions(db) {
  const { results } = await db.prepare('SELECT * FROM resolutions ORDER BY sort_order ASC, value_mm ASC').all();
  return results.map((r) => ({ id: r.id, v: r.value_mm, l: r.label }));
}

async function getHistory(db) {
  const { results } = await db.prepare('SELECT * FROM history ORDER BY saved_at DESC LIMIT 50').all();
  return results.map((h) => ({
    id: h.id,
    savedAt: h.saved_at,
    name: h.name,
    calc: JSON.parse(h.calc_json),
    result: JSON.parse(h.result_json),
  }));
}

export async function handleApi(request, env, url) {
  const db = env.DB;
  if (!db) return json({ error: 'Banco de dados não configurado (binding DB ausente).' }, 500);
  const { pathname } = url;
  const method = request.method;

  // ---- Estado inicial combinado ----
  if (pathname === '/api/state' && method === 'GET') {
    const [settings, filaments, printers, packagingTypes, resolutions, history] = await Promise.all([
      getSettings(db), getFilaments(db), getPrinters(db), getPackagingTypes(db), getResolutions(db), getHistory(db),
    ]);
    return json({ settings, filaments, printers, packagingTypes, resolutions, history });
  }

  // ---- Configurações / empresa ----
  if (pathname === '/api/settings' && method === 'GET') return json(await getSettings(db));
  if (pathname === '/api/settings' && method === 'PUT') {
    const body = await request.json();
    const cur = await db.prepare('SELECT * FROM settings WHERE id = 1').first();
    const merged = {
      company_name: body.companyName ?? cur.company_name,
      company_logo: body.companyLogo ?? cur.company_logo,
      company_phone: body.companyPhone ?? cur.company_phone,
      company_email: body.companyEmail ?? cur.company_email,
      company_cnpj: body.companyCnpj ?? cur.company_cnpj,
      company_address: body.companyAddress ?? cur.company_address,
      default_margin: body.defaultMargin ?? cur.default_margin,
      default_markup: body.defaultMarkup ?? cur.default_markup,
      default_taxes: body.defaultTaxes ?? cur.default_taxes,
      default_card_fee: body.defaultCardFee ?? cur.default_card_fee,
      default_energy_price: body.defaultEnergyPrice ?? cur.default_energy_price,
    };
    await db.prepare(
      `UPDATE settings SET company_name=?, company_logo=?, company_phone=?, company_email=?, company_cnpj=?, company_address=?,
       default_margin=?, default_markup=?, default_taxes=?, default_card_fee=?, default_energy_price=?, updated_at=datetime('now') WHERE id=1`
    ).bind(
      merged.company_name, merged.company_logo, merged.company_phone, merged.company_email, merged.company_cnpj, merged.company_address,
      merged.default_margin, merged.default_markup, merged.default_taxes, merged.default_card_fee, merged.default_energy_price
    ).run();
    return json(await getSettings(db));
  }

  if (pathname === '/api/settings/restore-defaults' && method === 'POST') {
    await db.prepare(
      `UPDATE settings SET company_name='DB Criações 3D', company_logo='', company_phone='', company_email='', company_cnpj='', company_address='',
       default_margin=5, default_markup=30, default_taxes=0, default_card_fee=0, default_energy_price=0.95, updated_at=datetime('now') WHERE id=1`
    ).run();
    return json(await getSettings(db));
  }

  if (pathname === '/api/settings/next-budget-number' && method === 'POST') {
    await db.prepare("UPDATE settings SET budget_seq = budget_seq + 1, updated_at=datetime('now') WHERE id = 1").run();
    const row = await db.prepare('SELECT budget_seq FROM settings WHERE id = 1').first();
    return json({ budgetSeq: row.budget_seq });
  }

  // ---- Filamentos ----
  if (pathname === '/api/filaments' && method === 'GET') return json(await getFilaments(db));
  if (pathname === '/api/filaments' && method === 'POST') {
    const b = await request.json();
    const id = uid('fil');
    await db.prepare('INSERT INTO filaments (id, name, category, price, extrusion, bed, desc, sort_order) VALUES (?,?,?,?,?,?,?,999)')
      .bind(id, b.name || 'Sem nome', b.category || 'Especial', Number(b.price) || 0, Number(b.extrusion) || 0, Number(b.bed) || 0, b.desc || 'Preset personalizado').run();
    return json(await getFilaments(db));
  }
  let m = pathname.match(/^\/api\/filaments\/([^/]+)$/);
  if (m && method === 'PUT') {
    const b = await request.json();
    await db.prepare('UPDATE filaments SET name=?, category=?, price=?, extrusion=?, bed=?, desc=? WHERE id=?')
      .bind(b.name, b.category || 'Especial', Number(b.price) || 0, Number(b.extrusion) || 0, Number(b.bed) || 0, b.desc || '', m[1]).run();
    return json(await getFilaments(db));
  }
  if (m && method === 'DELETE') {
    await db.prepare('DELETE FROM filaments WHERE id=?').bind(m[1]).run();
    return json(await getFilaments(db));
  }

  // ---- Impressoras ----
  if (pathname === '/api/printers' && method === 'GET') return json(await getPrinters(db));
  if (pathname === '/api/printers' && method === 'POST') {
    const b = await request.json();
    const id = uid('prt');
    await db.prepare('INSERT INTO printers (id, name, category, power, depreciation, desc, sort_order) VALUES (?,?,?,?,?,?,999)')
      .bind(id, b.name || 'Sem nome', b.category || 'FDM Intermediária', Number(b.power) || 0, Number(b.depreciation) || 0, b.desc || 'Preset personalizado').run();
    return json(await getPrinters(db));
  }
  m = pathname.match(/^\/api\/printers\/([^/]+)$/);
  if (m && method === 'PUT') {
    const b = await request.json();
    await db.prepare('UPDATE printers SET name=?, category=?, power=?, depreciation=?, desc=? WHERE id=?')
      .bind(b.name, b.category || 'FDM Intermediária', Number(b.power) || 0, Number(b.depreciation) || 0, b.desc || '', m[1]).run();
    return json(await getPrinters(db));
  }
  if (m && method === 'DELETE') {
    await db.prepare('DELETE FROM printers WHERE id=?').bind(m[1]).run();
    return json(await getPrinters(db));
  }

  // ---- Tipos de embalagem ----
  if (pathname === '/api/packaging-types' && method === 'GET') return json(await getPackagingTypes(db));
  if (pathname === '/api/packaging-types' && method === 'POST') {
    const b = await request.json();
    const id = uid('pkg');
    await db.prepare('INSERT INTO packaging_types (id, label, sort_order) VALUES (?,?,999)').bind(id, b.label || 'Sem nome').run();
    return json(await getPackagingTypes(db));
  }
  m = pathname.match(/^\/api\/packaging-types\/([^/]+)$/);
  if (m && method === 'PUT') {
    const b = await request.json();
    await db.prepare('UPDATE packaging_types SET label=? WHERE id=?').bind(b.label, m[1]).run();
    return json(await getPackagingTypes(db));
  }
  if (m && method === 'DELETE') {
    await db.prepare('DELETE FROM packaging_types WHERE id=?').bind(m[1]).run();
    return json(await getPackagingTypes(db));
  }

  // ---- Resoluções ----
  if (pathname === '/api/resolutions' && method === 'GET') return json(await getResolutions(db));
  if (pathname === '/api/resolutions' && method === 'POST') {
    const b = await request.json();
    const id = uid('res');
    await db.prepare('INSERT INTO resolutions (id, value_mm, label, sort_order) VALUES (?,?,?,999)').bind(id, Number(b.v) || 0, b.l || 'Sem nome').run();
    return json(await getResolutions(db));
  }
  m = pathname.match(/^\/api\/resolutions\/([^/]+)$/);
  if (m && method === 'PUT') {
    const b = await request.json();
    await db.prepare('UPDATE resolutions SET value_mm=?, label=? WHERE id=?').bind(Number(b.v) || 0, b.l, m[1]).run();
    return json(await getResolutions(db));
  }
  if (m && method === 'DELETE') {
    await db.prepare('DELETE FROM resolutions WHERE id=?').bind(m[1]).run();
    return json(await getResolutions(db));
  }

  // ---- Histórico ----
  if (pathname === '/api/history' && method === 'GET') return json(await getHistory(db));
  if (pathname === '/api/history' && method === 'POST') {
    const b = await request.json();
    const id = uid('hist');
    await db.prepare('INSERT INTO history (id, saved_at, name, calc_json, result_json) VALUES (?,?,?,?,?)')
      .bind(id, b.savedAt || new Date().toISOString(), b.name || 'Sem nome', JSON.stringify(b.calc || {}), JSON.stringify(b.result || {})).run();
    return json(await getHistory(db));
  }
  if (pathname === '/api/history' && method === 'DELETE') {
    await db.prepare('DELETE FROM history').run();
    return json([]);
  }
  m = pathname.match(/^\/api\/history\/([^/]+)$/);
  if (m && method === 'DELETE') {
    await db.prepare('DELETE FROM history WHERE id=?').bind(m[1]).run();
    return json(await getHistory(db));
  }

  return json({ error: 'Rota não encontrada' }, 404);
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (url.pathname.startsWith('/api/')) {
      try {
        return await handleApi(request, env, url);
      } catch (err) {
        return new Response(JSON.stringify({ error: String((err && err.message) || err) }), {
          status: 500,
          headers: { 'content-type': 'application/json; charset=utf-8' },
        });
      }
    }
    return new Response(APP_HTML, { headers: { 'content-type': 'text/html; charset=utf-8' } });
  },
};
